SELECT * FROM board_stats_daily

    AND board_id = #{p.boardId}
    AND stat_date >= #{p.from}
    AND stat_date <= #{p.to}

ORDER BY stat_date DESC, board_id
LIMIT 1000

SELECT * FROM board_stats_monthly

    AND board_id = #{p.boardId}
    AND stat_month >= #{p.from}
    AND stat_month <= #{p.to}

ORDER BY stat_month DESC, board_id
LIMIT 1000

